if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $required=['full_name','age','gender','phone','whatsapp','city','full_address','chief_complaint','symptoms','duration','severity']; foreach($required as $r){ if(trim((string)($_POST[$r]??''))==='') $errors[]="$r is required"; } if(empty($_POST['consent_checkbox'])) $errors[]='Consent is required'; if(empty($errors)){ $caseCode=generate_code('HT'); $form=$_POST; unset($form['csrf_token']); $safety=detect_emergency(json_encode_safe($form)); db()->beginTransaction(); db_execute('INSERT INTO patients (case_code,full_name,age,gender,phone,whatsapp,email,city,address,created_at) VALUES (?,?,?,?,?,?,?,?,?,NOW())', [$caseCode,$_POST['full_name'],(int)$_POST['age'],$_POST['gender'],$_POST['phone'],$_POST['whatsapp'],$_POST['email'] ?? '',$_POST['city'],$_POST['full_address']]); $pid=(int)db()->lastInsertId(); db_execute('INSERT INTO patient_cases (patient_id,case_code,chief_complaint,full_form_json,status,emergency_flag,ai_status,doctor_status,order_status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,NOW(),NOW())', [$pid,$caseCode,$_POST['chief_complaint'],json_encode_safe($form),'chat_started',$safety['emergency_flag']?1:0,'pending','pending','none']); $cid=(int)db()->lastInsertId(); db_execute('INSERT INTO chat_messages (case_id,sender_type,message,metadata_json,created_at) VALUES (?,?,?,?,NOW())', [$cid,'system','Consultation form submitted.',json_encode_safe(['case_code'=>$caseCode])]); db()->commit(); redirect('chat.php?case=' . urlencode($caseCode)); } }
public_header('Start Consultation'); ?>
